export async function* paginar(buscarPagina) {
  if (typeof buscarPagina !== 'function') throw new TypeError('buscarPagina deve ser função');
  const todos = [];
  let numero = 1;
  while (true) {
    const pagina = await buscarPagina(numero);
    todos.push(...pagina.itens);
    if (!pagina.temMais) break;
    numero += 1;
  }
  yield* todos;
}

export async function* paginar(buscarPagina) {
  if (typeof buscarPagina !== 'function') throw new TypeError('buscarPagina deve ser função');
  let numero = 1;
  while (true) {
    const pagina = await buscarPagina(numero);
    for (const item of pagina.itens) yield item;
    if (pagina.itens.length === 0) return;
    numero += 1;
  }
}

export async function* paginar(buscarPagina) {
