import { validar } from './main.js';

const pedido = {
  tipo: 'objeto',
  campos: {
    nome: { tipo: 'string' },
    quantidade: { tipo: 'number' },
    endereco: { tipo: 'objeto', campos: { cidade: { tipo: 'string' } } },
    itens: { tipo: 'lista', itens: { tipo: 'string' } },
    cupom: { tipo: 'string', opcional: true },
  },
};

describe('validar', () => {
  test('aceita um valor que segue o esquema e devolve o próprio valor', () => {
    const valor = { nome: 'Ana', quantidade: 2, endereco: { cidade: 'Recife' }, itens: ['caneta'] };
    const resultado = validar(pedido, valor);
    expect(resultado.ok).toBe(true);
    expect(resultado.valor).toBe(valor);
  });
  test('campo opcional ausente é aceito', () => {
    const resultado = validar(pedido, { nome: 'Ana', quantidade: 1, endereco: { cidade: 'X' }, itens: [] });
    expect(resultado.ok).toBe(true);
  });
  test('erro de campo aninhado carrega o caminho completo', () => {
    const resultado = validar(pedido, { nome: 'Ana', quantidade: 1, endereco: { cidade: 7 }, itens: [] });
    expect(resultado.ok).toBe(false);
    expect(resultado.erros).toEqual([{ caminho: 'endereco.cidade', mensagem: 'deve ser string' }]);
  });
  test('cada item inválido de uma lista é reportado com o índice', () => {
    const resultado = validar(pedido, { nome: 'Ana', quantidade: 1, endereco: { cidade: 'X' }, itens: ['ok', 3, 'ok', null] });
    expect(resultado.erros).toEqual([
      { caminho: 'itens[1]', mensagem: 'deve ser string' },
      { caminho: 'itens[3]', mensagem: 'deve ser string' },
    ]);
  });
  test('reporta todos os erros, não só o primeiro', () => {
    const resultado = validar(pedido, { nome: 1, quantidade: 'x', endereco: null, itens: 'a' });
    expect(resultado.erros.map(erro => erro.caminho)).toEqual(['nome', 'quantidade', 'endereco', 'itens']);
  });
  test('objeto raiz que não é objeto gera erro na raiz', () => {
    expect(validar(pedido, [1]).erros).toEqual([{ caminho: '', mensagem: 'deve ser objeto' }]);
  });
  test('não altera o valor validado', () => {
    const valor = Object.freeze({ nome: 'Ana', quantidade: 1, endereco: { cidade: 'X' }, itens: ['a'] });
    expect(validar(pedido, valor).ok).toBe(true);
    expect(valor.itens).toEqual(['a']);
  });
});

